# 1. Guardar el logo
echo "$LOGO_B64" | base64 -d > "$STATIC/logo.png"
echo "✓ logo.png guardado ($(du -h $STATIC/logo.png | cut -f1))"

# 2. Reemplazar "Mi negocio" → "OnlyReef" en todos los archivos
echo ""
echo "Actualizando nombre de la empresa..."
for f in "$STATIC"/*.html; do
  sed -i 's/Mi negocio/OnlyReef/g' "$f"
  sed -i 's/Mi Negocio/OnlyReef/g' "$f"
done
echo "✓ Nombre actualizado en $(ls $STATIC/*.html | wc -l) páginas"

# 3. Actualizar <title> de cada página
declare -A TITULOS=(
  ["login.html"]="OnlyReef"
  ["menu.html"]="OnlyReef"
  ["index.html"]="Inventario · OnlyReef"
  ["precios.html"]="Precios · OnlyReef"
  ["pagos.html"]="Punto de venta · OnlyReef"
  ["historial.html"]="Historial · OnlyReef"
  ["usuarios.html"]="Usuarios · OnlyReef"
  ["inv_sucursales.html"]="Inventario por sucursal · OnlyReef"
)
for archivo in "${!TITULOS[@]}"; do
  f="$STATIC/$archivo"
  [ -f "$f" ] || continue
  titulo="${TITULOS[$archivo]}"
  sed -i "s|<title>.*</title>|<title>$titulo</title>|g" "$f"
done
echo "✓ Títulos de pestaña actualizados"

# 4. Reemplazar emoji 🔐 en login por el logo OnlyReef
python3 << 'PYEOF'
import re, os
static = os.path.expanduser('~/inventario/static')

# ── login.html: logo grande centrado ──────────────────────────────────────
f = os.path.join(static, 'login.html')
if os.path.exists(f):
    src = open(f).read()
    # Reemplazar el emoji de ícono por el logo
    src = re.sub(
        r'<div class="ico">.*?</div>',
        '<div class="ico"><img src="/static/logo.png" alt="OnlyReef" style="width:140px;height:auto"></div>',
        src, flags=re.DOTALL
    )
    open(f,'w').write(src)
    print('✓ login.html: logo integrado')

# ── menu.html: logo en topbar y en el header ──────────────────────────────
f = os.path.join(static, 'menu.html')
if os.path.exists(f):
    src = open(f).read()
    # Reemplazar el topbar-title con logo + texto
    src = src.replace(
        '<h1 class="topbar-title">OnlyReef</h1>',
        '<h1 class="topbar-title"><img src="/static/logo.png" alt="OnlyReef" style="height:34px;width:auto;vertical-align:middle"> OnlyReef</h1>'
    )
    # Reemplazar encabezado del menú si existe
    src = re.sub(
        r'<div class="menu-header">(.*?)</div>',
        '<div class="menu-header"><img src="/static/logo.png" alt="OnlyReef" style="height:80px;width:auto;margin-bottom:.5rem"><br>Bienvenido</div>',
        src, flags=re.DOTALL
    )
    open(f,'w').write(src)
    print('✓ menu.html: logo en topbar')

# ── Todas las páginas: agregar logo pequeño en btn-inicio si lo hay ────────
pages = ['index.html','precios.html','pagos.html','historial.html',
         'usuarios.html','inv_sucursales.html']
for page in pages:
    f = os.path.join(static, page)
    if not os.path.exists(f): continue
    src = open(f).read()
    # Agregar favicon de OnlyReef (pestaña del navegador)
    if 'link rel="icon"' not in src:
        src = src.replace(
            '<meta charset="UTF-8">',
            '<meta charset="UTF-8">\n<link rel="icon" type="image/png" href="/static/logo.png">'
        )
    open(f,'w').write(src)

# ── Favicon en login y menu también ───────────────────────────────────────
for page in ['login.html','menu.html']:
    f = os.path.join(static, page)
    if not os.path.exists(f): continue
    src = open(f).read()
    if 'link rel="icon"' not in src:
        src = src.replace(
            '<meta charset="UTF-8">',
            '<meta charset="UTF-8">\n<link rel="icon" type="image/png" href="/static/logo.png">'
        )
    open(f,'w').write(src)

print('✓ Favicon OnlyReef agregado a todas las páginas')

# ── Ticket: asegurar que dice OnlyReef ────────────────────────────────────
for page in ['pagos.html', 'historial.html']:
    f = os.path.join(static, page)
    if not os.path.exists(f): continue
    src = open(f).read()
    src = src.replace('Mi negocio', 'OnlyReef').replace('Mi Negocio', 'OnlyReef')
    open(f,'w').write(src)

print('✓ Tickets actualizados con nombre OnlyReef')
PYEOF

echo ""
echo "✅ Personalización completa. Reiniciando servicio..."
sudo systemctl restart inventario
echo "🚀 ¡Listo! La app ya muestra el logo de OnlyReef."
